	Encoder
}

func (n NopCloseEncoder) Close() error { return nil }

func (e Encoding) NewDecoder(r io.Reader) Decoder {
	switch e {
	case EncodingYML, EncodingYAML:
		return yaml.NewDecoder(r)
	case EncodingJSON:
		return json.NewDecoder(r)
	}

	return nil
}

type Decoder interface {
	Decode(any) error
}

